class Solution {
    public ListNode middleOfLinkedList(ListNode head) {
        ListNode tortoise = head;
        ListNode hare = head;
        while(hare.next != null && hare.next.next != null){
            tortoise=tortoise.next;
            hare=hare.next.next;
        }
        if(hare.next != null){
            return tortoise.next;
        }else{
            return tortoise;
        }
    }
}

